// PF-16 God of Consequences. Controlled experiments that use only interventions the scientific model supports:
//   • axial tilt — the experimental world is regenerated by the same model (glacial-0.8) with a different tilt;
//   • glacial forcing — the world's computed glacial-maximum state is compared with its present state.
// The baseline world object is never modified; the experiment is a separate object that can be discarded (revert).
// Other interventions (terraforming, ocean engineering, atmospheric chemistry) would need new validated models.
import { createPlanet, BIOMES, KOPPEN } from '../planet.js';
import { GLACIAL_CELL } from '../glaciation.js';

export const INTERVENTIONS = { tilt: 'Change the axial tilt (full model re-run)', glacial: 'Impose the glacial maximum (computed state)' };
const desert = new Set(['Subtropical desert', 'Cold desert'].map(b => BIOMES.indexOf(b)));

export function metrics(p, glacial = false) {
  let land = 0, t = 0, tLand = 0, des = 0, ice = 0, mild = 0, rain = 0; const g = glacial ? p.glaciation : null;
  for (let i = 0; i < p.cellCount; i++) {
    const T = glacial ? p.temperature[i] - g.stats.globalCoolingK : p.temperature[i], isLand = glacial ? p.elevation[i] >= -g.stats.seaLevelFallM || g.cell[i] === GLACIAL_CELL.ice : p.elevation[i] >= 0; // glacial sea stands seaLevelFallM lower
    t += T; if (!isLand) continue; land++; tLand += T; rain += p.rainfall[i];
    const iced = glacial ? g.cell[i] === GLACIAL_CELL.ice : KOPPEN[p.koppen[i]] === 'EF';
    if (iced) ice++; else if (!glacial && desert.has(p.biome[i])) des++;
    if (!iced && T >= 0 && T <= 25 && p.rainfall[i] >= 400) mild++;
  }
  return { meanTempC: +(t / p.cellCount).toFixed(2), landMeanTempC: +(tLand / land).toFixed(2), landFraction: +(land / p.cellCount).toFixed(4), iceLandShare: +(ice / land).toFixed(4), desertLandShare: glacial ? null : +(des / land).toFixed(4), habitableLandShare: +(mild / land).toFixed(4), meanLandRainMm: Math.round(rain / land) };
}
/** Run an experiment against a baseline planet. Returns the experiment world (if any), metrics and per-cell ΔT. */
export function runExperiment(base, mesh, intervention, value) {
  const before = metrics(base);
  if (intervention === 'glacial') {
    const after = metrics(base, true), dT = new Float32Array(base.cellCount).fill(-base.glaciation.stats.globalCoolingK);
    return { intervention, value: null, world: null, before, after, dT, note: 'Glacial maximum from the glaciation model (uniform global cooling shown; ice and coastlines from the computed state).' };
  }
  if (!(value >= 0 && value <= 90)) return { error: 'tilt must be 0–90°' };
  const world = createPlanet(base.seed, { frequency: base.frequency, mesh, tilt: value }), after = metrics(world), dT = new Float32Array(base.cellCount);
  for (let i = 0; i < base.cellCount; i++) dT[i] = world.temperature[i] - base.temperature[i];
  return { intervention, value, world, before, after, dT, note: `Same seed and model (${world.version}) re-run with tilt ${value}° (baseline ${base.tilt}°). Relief is unchanged; climate, hydrology and biomes are recomputed.` };
}
export function delta(before, after) { const out = {}; for (const k of Object.keys(before)) out[k] = before[k] === null || after[k] === null ? null : +(after[k] - before[k]).toFixed(4); return out; }
